package dns
import("context";"fmt";"net";"strings";"time")
type DNSProbe struct{Address string `json:"address"`;Name string `json:"name"`;Timeout time.Duration `json:"timeout"`}
type DNSProbeResult struct{Address string `json:"address"`;Reachable bool `json:"reachable"`;Latency time.Duration `json:"latency"`;Error string `json:"error,omitempty"`}
func(p DNSProbe)Validate()error{address:=strings.TrimSpace(p.Address);if address==""{return fmt.Errorf("DNS probe address is required")};if p.Timeout<=0{return fmt.Errorf("DNS probe timeout must be positive")};if _,_,err:=net.SplitHostPort(address);err!=nil{return fmt.Errorf("DNS probe address must include host and port")};return nil}
func(p DNSProbe)Probe(ctx context.Context)DNSProbeResult{result:=DNSProbeResult{Address:strings.TrimSpace(p.Address)};if ctx==nil{result.Error="context is required";return result};if err:=p.Validate();err!=nil{result.Error=err.Error();return result};if err:=ctx.Err();err!=nil{result.Error=err.Error();return result};start:=time.Now();d:=net.Dialer{Timeout:p.Timeout};conn,err:=d.DialContext(ctx,"udp",result.Address);result.Latency=time.Since(start);if err!=nil{result.Error=err.Error();return result};if err:=conn.Close();err!=nil{result.Error=err.Error();return result};result.Reachable=true;return result}
